using System.Buffers;
using System.Globalization;

public static class ZeroAllocParser
{
    /// <summary>
    /// Parses one line of comma-separated integers into <paramref name="destination"/>.
    /// Tokens are trimmed; empty tokens are skipped. Returns the number of ints written.
    /// Uses an IndexOf loop so it compiles on .NET 8 (the span Split enumerator is .NET 9+).
    /// </summary>
    public static int ParseInts(ReadOnlySpan<char> line, Span<int> destination)
    {
        int written = 0;
        ReadOnlySpan<char> rest = line;
        while (true)
        {
            int comma = rest.IndexOf(',');
            ReadOnlySpan<char> token = (comma < 0 ? rest : rest[..comma]).Trim();

            if (!token.IsEmpty)
            {
                if (!int.TryParse(token, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value))
                    throw new FormatException($"'{token}' is not a valid integer."); // allocates only on the error path

                if (written == destination.Length)
                    throw new ArgumentException("Destination buffer is too small.", nameof(destination));

                destination[written++] = value;
            }

            if (comma < 0) return written;
            rest = rest[(comma + 1)..];
        }
    }

    /// <summary>
    /// Sums every integer in a multi-line text. Streams line by line and never materialises
    /// lines or tokens. A single small stack buffer covers typical lines; longer lines rent
    /// from ArrayPool and return the array in a finally block.
    /// </summary>
    public static long SumAll(ReadOnlySpan<char> text)
    {
        const int StackLimit = 128;
        long sum = 0;
        Span<int> stackBuffer = stackalloc int[StackLimit];          // once, before the loop (CA2014)

        foreach (ReadOnlySpan<char> line in text.EnumerateLines())     // handles \n, \r\n and \r (.NET 6+)
        {
            if (line.IsWhiteSpace()) continue;

            int maxValues = line.Count(',') + 1;                        // upper bound on tokens in this line
            int[]? rented = maxValues <= StackLimit ? null : ArrayPool<int>.Shared.Rent(maxValues);
            Span<int> buffer = rented ?? stackBuffer;                   // rented may be longer than maxValues
            try
            {
                int n = ParseInts(line, buffer);
                foreach (int v in buffer[..n]) sum += v;                // read only the written prefix
            }
            finally
            {
                if (rented is not null) ArrayPool<int>.Shared.Return(rented);
            }
        }
        return sum;
    }
}

public static class Program
{
    public static void Main()
    {
        Span<int> buf = stackalloc int[16];

        int n = ZeroAllocParser.ParseInts("  12, -7 ,300,,4 ", buf);
        Console.WriteLine($"ParseInts -> {n}: {string.Join(", ", buf[..n].ToArray())}");   // 4: 12, -7, 300, 4
        Console.WriteLine($"ParseInts(\"\") -> {ZeroAllocParser.ParseInts("", buf)}");       // 0

        try { ZeroAllocParser.ParseInts("1,x", buf); }
        catch (FormatException e) { Console.WriteLine($"FormatException: {e.Message}"); }

        try { ZeroAllocParser.ParseInts("1,2,3", buf[..2]); }
        catch (ArgumentException e) { Console.WriteLine($"ArgumentException: {e.Message}"); }

        Console.WriteLine($"SumAll -> {ZeroAllocParser.SumAll("1,2,3\r\n\n 4 , 5 \n,6,\n")}"); // 21
        Console.WriteLine($"SumAll(\"\") -> {ZeroAllocParser.SumAll("")}");                     // 0

        // A line with more values than the stack cap forces the ArrayPool path.
        string longLine = string.Join(",", Enumerable.Range(1, 1000));
        string text = string.Concat(Enumerable.Repeat("1,2,3\n" + longLine + "\n", 50));
        Console.WriteLine($"SumAll(long) -> {ZeroAllocParser.SumAll(text)}");                  // 50 * (6 + 500500)

        // Warm up (JIT, pool bucket) and then measure allocations over 1,000 calls.
        ZeroAllocParser.SumAll(text);
        long before = GC.GetAllocatedBytesForCurrentThread();
        for (int i = 0; i < 1_000; i++) ZeroAllocParser.SumAll(text);
        long after = GC.GetAllocatedBytesForCurrentThread();
        Console.WriteLine($"Allocated over 1,000 SumAll calls: {after - before} bytes");        // 0
    }
}

